{"source": "def investigate(context, acquire):
    events = context.get('events', [])
    count = 0
    status = 'open'
    pending = []
    for ev in events:
        op = ev.get('op')
        if op == 'reset':
            count = 0
            status = 'open'
            pending = []
        elif op == 'feed':
            if status != 'open':
                continue
            data = ev.get('bytes', [])
            pending.extend(data)
            i = 0
            n = len(pending)
            while i < n:
                b = pending[i]
                if b < 128:
                    count += 1
                    i += 1
                elif b < 194:
                    status = 'error'
                    break
                elif b < 224:
                    if i + 1 >= n:
                        break
                    b2 = pending[i+1]
                    if b2 < 128 or b2 > 191:
                        status = 'error'
                        break
                    count += 1
                    i += 2
                elif b < 240:
                    if i + 2 >= n:
                        break
                    b2 = pending[i+1]
                    b3 = pending[i+2]
                    if b2 < 128 or b2 > 191 or b3 < 128 or b3 > 191:
                        status = 'error'
                        break
                    if b == 224 and b2 < 160:
                        status = 'error'
                        break
                    if b == 237 and b2 > 159:
                        status = 'error'
                        break
                    count += 1
                    i += 3
                elif b < 245:
                    if i + 3 >= n:
                        break
                    b2 = pending[i+1]
                    b3 = pending[i+2]
                    b4 = pending[i+3]
                    if b2 < 128 or b2 > 191 or b3 < 128 or b3 > 191 or b4 < 128 or b4 > 191:
                        status = 'error'
                        break
                    if b == 240 and b2 < 144:
                        status = 'error'
                        break
                    if b == 244 and b2 > 143:
                        status = 'error'
                        break
                    count += 1
                    i += 4
                else:
                    status = 'error'
                    break
            if status == 'error':
                pending = []
            else:
                pending = pending[i:]
        elif op == 'finish':
            if status != 'open':
                continue
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
    return {'count': count, 'status': status}
